using Microsoft.Extensions.DependencyInjection;
using Npgsql;

namespace SaaSFoundry.Persistence.Connection;

public static class NpgsqlConnectionSetupExtensions
{
    public static IServiceCollection AddSaaSFoundryPersistence(this IServiceCollection services, string connectionString = "Host=localhost;Database=postgres;Username=postgres")
    {
        services.AddNpgsqlDataSource(connectionString);
        return services;
    }
}